public boolean remove(int val) {
        if (size == 0) {
            return false;
        }
        int index = 0;
        if (val == heap[0]) {
            heap[0] = heap[--size];
            siftDown(0);
            return true;
        }
        for (int i = 1; i < size; i++) {
            if (heap[i] == val) {
                index = i;
                break;
            }
        }
        if (index != 0) {
            heap[index] = heap[--size];
            if (index < size) {
                if (heap[parent(index)] > heap[index]) {
                    siftUp(index);
                } else {
                    siftDown(index);
                }
            }
            return true;
        }
        return false;
    }

