public long readRawVarint64() throws IOException {
        int shift = 0;
        long result = 0;
        while (true) {
            byte b = read();
            if (b == -1) throw EOFException();
            if ((b & 0x80) == 0) {
                return (int) b | (result << 7);
            } else {
                result |= (long) (b & 0x7f) << shift;
                shift += 7;
                if (shift >= 64) {
                    throw new IllegalArgumentException(
                            "varint decimal too large");
                }
            }
        }
    }

