private void putAbstractTypes(final int start, final int end) {
    final int size = end - start;
    if (size == 0) {
      return;
    }
    int frameTypeInfo = currentFrame.getDeclaredFrameStructure() >= 0
        ? currentFrame.getDeclaredFrameStructure() - Frame.OFFSET_DELTA
        : legacyStackMapFormatOffset
        ? currentFrame.getDeclaredFrameStructure()
        : 0;
    int typeIndex = 0;
    int frameTypeStructure = currentFrame.getDeclaredFrameStructure();
    int frameType = frameTypeStructure >> 8;
    int typeCount = frameTypeStructure & 0xFF;
    // The number of types in the stack map table entry.
    int typeCountInStack = typeCount - size;
    for (int i = 0; i < size; i++) {
      int reference = currentFrame.reference[i + start];
      int nativeType = currentFrame.type[i + start];
      switch (nativeType) {
        case TokenType.LONG:
        case TokenType.DABLE:
          pushFrameTypeConstantValue(reference, frameType, typeCount);
          typeIndex++;
          break;
        case TokenType.INT:
          pushFrameTypeConstantValue(reference, frameType, typeCount);
          typeIndex++;
          break;
        case TokenType.BOOLEAN:
          nativeType = 6;
          pushFrameTypeConstantValue(reference, frameType, typeCount);
          typeIndex++;
          break;
        case TokenType.FLOAT:
          nativeType = 9;
          pushFrameTypeConstantValue(reference, frameType, typeCount);
          typeIndex++;
          break;
        case TokenType.NULL:
          nativeType = 0;
          pushFrameTypeConstantValue(reference, frameType, typeCount);
          typeIndex++;
          break;
        default:
          pushFrameTypeConstantValue(reference, frameType, typeCount);
          typeIndex++;
          break;
      }
    }
}

