public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder builder = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'a':
                    builder.append('\u0007');
                    break;
                case 'b':
                    builder.append('\b');
                    break;
                case 'f':
                    builder.append('\f');
                    break;
                case 'n':
                    builder.append('\n');
                    break;
                case 'r':
                    builder.append('\r');
                    break;
                case 't':
                    builder.append('\t');
                    break;
                case 'u':
                    if (i + 5 < len) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            builder.append((char) val);
                            i += 4;
                        } catch (NumberFormatException e) {
                            builder.append('\\');
                        }
                    } else {
                        builder.append('\\');
                    }
                    break;
                case '"':
                    builder.append('"');
                    break;
                case '\'':
                    builder.append('\'');
                    break;
                case '\\':
                    builder.append('\\');
                    break;
                case 'x':
                    if (i + 3 < len) {
                        String hex = str.substring(i + 2, i + 4);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            builder.append((char) val);
                            i += 2;
                        } catch (NumberFormatException e) {
                            builder.append('\\');
                        }
                    } else {
                        builder.append('\\');
                    }
                    break;
                case '0':
                case '1':
                case '2':
                case '3':
                case '4':
                case '5':
                case '6':
                case '7':
                    int start = i + 1;
                    int end = start;
                    while (end < len && end < start + 3) {
                        char digit = str.charAt(end);
                        if (digit < '0' || digit > '7') {
                            break;
                        }
                        end++;
                    }
                    try {
                        int val = Integer.parseInt(str.substring(start, end), 8);
                        builder.append((char) val);
                        i = end - 1;
                    } catch (NumberFormatException e) {
                        builder.append('\\');
                    }
                    break;
                default:
                    builder.append('\\');
                    break;
            }
            i++;
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

