private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        List<K> leftSubtree = keys.subList(0, i);
        maxLowerBound = Integer.MAX_VALUE;
        for (K leftKey : leftSubtree) {
            int bound = getKeyLowerBound(leftKey, key);
            if (bound < maxLowerBound) {
                maxLowerBound = bound;
            }
        }
        lowerBounds.add(maxLowerBound);
    }
    return lowerBounds;
}

