private void checkIfPackedField() throws IOException {
    int bitpos = afterBitPosition;
    int wireType = wireTypeFromTag;
    if (wireType == WIRETYPE_LENGTH_DELIMITED) {
        if (isPackedField) {
            isPackedField = false;
            repeatedFieldSize = readRawVarint32();
            packedState = PackedState.NON_PACKED;
            afterBitPosition = bitpos;
            return;
        }
    }
    if (!isPackedField) {
        packedState = PackedState.NON_PACKED;
    } else {
        packedState = PackedState.PACKED;
    }
    afterBitPosition = bitpos;
}

